def canonical_name(name):
    """'  carabus   NEMORALIS ' -> 'Carabus nemoralis': the genus capitalised, everything after
    it lowercase, one space between words."""
    words = name.split()
    if not words:
        return ""
    return " ".join([words[0].capitalize()] + [word.lower() for word in words[1:]])

